下面示例基于 Express，包含： Last-Event-ID / lastEventId 查询参数续传。 心跳保活。 简单的 token 缓存与断线续传逻辑（内存示例，生产建议换持久化存储）。 import express from "express"; import type { Request, Response } from "express"; type TokenEvent = { id: string; data: string; }; const app = express(); // 简单内存缓存：按会话缓存已发送 token const conversationCache = new Map<string, TokenEvent[]>(); function writeEvent(res: Response, evt: TokenEvent, eventName = "message") { res.write(`id: ${evt.id}
`); res.write(`event: ${eventName}
`); res.write(`data: ${evt.data}

`); } function writeHeartbeat(res: Response) { res.write(`event: heartbeat
data: ok

`); } app.get("/api/chat/stream", async (req: Request, res: Response) => { res.set({ "Content-Type": "text/event-stream; charset=utf-8", "Cache-Control": "no-cache", Connection: "keep-alive", "X-Accel-Buffering": "no", }); res.flushHeaders(); const conversationId = String(req.query.cid || "default"); const lastEventId = String(req.headers["last-event-id"] || "") || String(req.query.lastEventId || ""); // 断线续传：补发 lastEventId 之后的事件 const cached = conversationCache.get(conversationId) || []; if (lastEventId) { const lastIndex = cached.findIndex((e) => e.id === lastEventId); const replay = lastIndex >= 0 ? cached.slice(lastIndex + 1) : cached; for (const evt of replay) writeEvent(res, evt); } // 心跳定时器 const heartbeatTimer = setInterval(() => { writeHeartbeat(res); }, 10000); // 模拟 AI token 流 let counter = cached.length; const tokens = ["你好，", "这是 ", "SSE ", "流式 ", "输出。"]; const streamTimer = setInterval(() => { if (counter >= tokens.length) { clearInterval(streamTimer); res.write(`event: done
data: ok

`); res.end(); return; } const evt = { id: String(counter + 1), data: tokens[counter] }; const list = conversationCache.get(conversationId) || []; list.push(evt); conversationCache.set(conversationId, list); writeEvent(res, evt); counter += 1; }, 700); req.on("close", () => { clearInterval(streamTimer); clearInterval(heartbeatTimer); }); }); app.listen(3000);
